<template><form class="scb-form scb-ops-form" @submit.prevent="save"><h2>{{draft.id?'Edit program':'Add a program'}}</h2><label>Title<input v-model="draft.title" required maxlength="200"/></label><div class="scb-ops-grid"><label>Program label<select v-model="draft.programType"><option v-for="(v,k) in types" :key="k" :value="k">{{v}}</option></select></label><label>Audience<select v-model="draft.audience"><option v-for="(v,k) in audiences" :key="k" :value="k">{{v}}</option></select></label><label>Program owner<input v-model="draft.ownerName" required maxlength="200"/></label><label>Sponsor, if applicable<input v-model="draft.sponsorName" maxlength="200" :required="draft.programType==='sponsored'"/></label></div><label>Description<textarea v-model="draft.description" required rows="4" maxlength="8000"/></label><div class="scb-ops-grid"><label>Presenter name<input v-model="draft.presenterName" required maxlength="200"/></label><label>Presenter account (optional)<select v-model="draft.presenterUserId"><option :value="null">External presenter</option><option v-for="p in workspace.presenters" :key="p.id" :value="p.id">{{p.first_name}} {{p.last_name}}</option></select></label></div><label>Presenter introduction<textarea v-model="draft.presenterBio" rows="2" maxlength="4000"/></label><label>Service regions, separated by commas<input v-model="regions" required placeholder="Denver Metro, Northern Colorado"/></label><div class="scb-ops-grid"><label>Delivery<select v-model="draft.deliveryMode"><option value="in_person">In person</option><option value="virtual">Virtual</option><option value="both">In person or virtual</option></select></label><label>Duration (minutes)<input v-model.number="draft.durationMinutes" type="number" min="15" max="1440" required/></label><label>Maximum attendance<input v-model.number="draft.capacity" type="number" min="1" required/></label><label>Funding<select v-model="draft.fundingMode"><option value="cash">Cash</option><option value="grant">Grant funded</option><option value="mixed">Cash or approved funding</option><option value="free">Free to the school</option></select></label><label>Published price (USD; blank for quote)<input v-model="price" type="number" min="0" step="0.01"/></label><label>Finance program<select v-model="draft.financeProgramId"><option :value="null">Not linked yet</option><option v-for="p in workspace.financePrograms" :key="p.id" :value="p.id">{{p.name}}</option></select></label></div><label class="scb-ops-check"><input v-model="draft.travelAvailable" type="checkbox"/> Accept travel inquiries outside these regions</label><details><summary>Link existing session registration</summary><p>Use an existing class or event registration. Its enrollment rules, forms, capacity and payment workflow continue to apply.</p><label>Class<select v-model="draft.registrationClassId" @change="draft.registrationEventId=null"><option :value="null">None</option><option v-for="c in workspace.registrationClasses" :key="c.id" :value="c.id">{{c.class_name}}</option></select></label><label>Event<select v-model="draft.registrationEventId" @change="draft.registrationClassId=null"><option :value="null">None</option><option v-for="c in workspace.registrationEvents" :key="c.id" :value="c.id">{{c.title}}</option></select></label></details><label class="scb-ops-check"><input v-model="draft.published" type="checkbox"/> Publish this reviewed offering on the SchoolCareBridge website</label><div class="scb-actions"><button class="scb-button" :disabled="busy">Save program</button><button type="button" class="scb-button scb-outline" @click="$emit('close')">Close</button></div></form></template>
<script setup>
import {ref} from 'vue';
const props=defineProps({program:Object,workspace:Object,busy:Boolean}),emit=defineEmits(['save','close']);
const types={original:'MH4Kidz Original',partner:'Community Partner',managed:'SchoolCareBridge Managed',sponsored:'MH4Kidz Sponsored'},audiences={students:'Students',parents:'Parents & families',staff:'School staff',school_wide:'School-wide'};
const draft=ref({title:'',programType:'original',ownerName:'MH4Kidz',audience:'parents',description:'',deliveryMode:'both',presenterName:'',presenterUserId:null,presenterBio:'',travelAvailable:false,durationMinutes:60,capacity:30,fundingMode:'cash',sponsorName:'',financeProgramId:null,registrationClassId:null,registrationEventId:null,published:false,...props.program});
const price=ref(draft.value.priceCents==null?'':(draft.value.priceCents/100).toFixed(2)),regions=ref((draft.value.regions||[]).join(', '));
function save(){emit('save',{...draft.value,regions:regions.value.split(',').map(r=>r.trim()).filter(Boolean),priceCents:price.value===''?null:Math.round(Number(price.value)*100)});}
</script>
